contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function with inputs: deposit amount to send
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        // Record contract balance before any interaction
        uint before = address(c).balance;
        // Make a deposit of `amount` into c
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;
        // Balance immediately after deposit
        uint afterDeposit = address(c).balance;

        // Now attempt withdrawAll and observe whether it reverts
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterWithdraw = address(c).balance;

        // General invariant: withdrawAll cannot increase c's balance.
        // If it reverted, balance must equal afterDeposit. Otherwise balance must be <= afterDeposit.
        assert(reverted ? (afterWithdraw == afterDeposit) : (afterWithdraw <= afterDeposit));
    }

    // allow receiving refunds if needed
    receive() external payable {}
}

